/**
 * Robust Prescription Storage Utility
 * Supports IndexedDB + LocalStorage with Image Optimization to prevent QuotaExceededError
 * and ensure prescriptions persist reliably across page refreshes on macOS Safari, Chrome, and iOS.
 */

const DB_NAME = "4cps_prescriptions_db";
const DB_VERSION = 1;
const STORE_NAME = "prescriptions_store";

// Open IndexedDB instance safely
const openDB = () => {
  return new Promise((resolve) => {
    if (typeof window === "undefined" || !window.indexedDB) {
      resolve(null);
      return;
    }
    try {
      const request = window.indexedDB.open(DB_NAME, DB_VERSION);
      request.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME);
        }
      };
      request.onsuccess = (e) => {
        resolve(e.target.result);
      };
      request.onerror = () => {
        resolve(null);
      };
    } catch (err) {
      resolve(null);
    }
  });
};

// Save a key-value pair to IndexedDB
export const saveToIndexedDB = async (key, value) => {
  try {
    const db = await openDB();
    if (!db) return;
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(value, key);
  } catch (e) {
    console.warn("IndexedDB save warning:", e);
  }
};

// Retrieve a key-value pair from IndexedDB
export const getFromIndexedDB = async (key) => {
  try {
    const db = await openDB();
    if (!db) return null;
    return new Promise((resolve) => {
      const tx = db.transaction(STORE_NAME, "readonly");
      const store = tx.objectStore(STORE_NAME);
      const req = store.get(key);
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch (e) {
    console.warn("IndexedDB get warning:", e);
    return null;
  }
};

// Remove key from IndexedDB
export const removeFromIndexedDB = async (key) => {
  try {
    const db = await openDB();
    if (!db) return;
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.delete(key);
  } catch (e) {}
};

/**
 * Compress an image file to ~150KB-250KB JPEG to fit easily in localStorage without QuotaExceededError.
 */
export const compressPrescriptionFile = (file) => {
  return new Promise((resolve) => {
    const isImage = file.type && (file.type.includes("image") || file.name.match(/\.(jpg|jpeg|png|webp)$/i));
    const reader = new FileReader();

    reader.onload = (event) => {
      const rawDataUrl = event.target.result;
      if (!isImage || !rawDataUrl || typeof rawDataUrl !== "string") {
        resolve({
          name: file.name,
          type: file.type || "application/pdf",
          size: file.size,
          data: rawDataUrl,
          url: rawDataUrl,
        });
        return;
      }

      // Optimize image dimensions and compression
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement("canvas");
        let width = img.width;
        let height = img.height;
        const maxDim = 1600;

        if (width > maxDim || height > maxDim) {
          if (width > height) {
            height = Math.round((height * maxDim) / width);
            width = maxDim;
          } else {
            width = Math.round((width * maxDim) / height);
            height = maxDim;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext("2d");
        ctx.fillStyle = "#ffffff";
        ctx.fillRect(0, 0, width, height);
        ctx.drawImage(img, 0, 0, width, height);

        const optimizedDataUrl = canvas.toDataURL("image/jpeg", 0.85);
        resolve({
          name: file.name,
          type: "image/jpeg",
          size: Math.round((optimizedDataUrl.length * 3) / 4),
          data: optimizedDataUrl,
          url: optimizedDataUrl,
        });
      };

      img.onerror = () => {
        resolve({
          name: file.name,
          type: file.type || "image/jpeg",
          size: file.size,
          data: rawDataUrl,
          url: rawDataUrl,
        });
      };

      img.src = rawDataUrl;
    };

    reader.onerror = () => {
      resolve(null);
    };

    reader.readAsDataURL(file);
  });
};

/**
 * Synchronously load category prescriptions from LocalStorage.
 */
export const getStoredCategoryPrescriptionsSync = () => {
  let map = {};
  try {
    const savedMap = localStorage.getItem("uploaded_prescriptions_by_category");
    if (savedMap) {
      map = JSON.parse(savedMap);
    }
  } catch (e) {}

  if (Object.keys(map).length === 0) {
    try {
      const legacyPrescs = JSON.parse(localStorage.getItem("uploaded_prescriptions") || "[]");
      const legacyCat = localStorage.getItem("prescriptionCategory") || "Medicines & Cosmetics";
      if (Array.isArray(legacyPrescs) && legacyPrescs.length > 0) {
        map[legacyCat] = legacyPrescs;
      }
    } catch (e) {}
  }
  return map;
};

/**
 * Asynchronously load category prescriptions, with IndexedDB recovery if LocalStorage is empty.
 */
export const getStoredCategoryPrescriptionsAsync = async () => {
  let map = getStoredCategoryPrescriptionsSync();
  if (Object.keys(map).length > 0) {
    // Also backup to IndexedDB
    saveToIndexedDB("uploaded_prescriptions_by_category", map);
    return map;
  }

  // Attempt recovery from IndexedDB (e.g. on Safari refresh where localStorage was restricted)
  const idbMap = await getFromIndexedDB("uploaded_prescriptions_by_category");
  if (idbMap && typeof idbMap === "object" && Object.keys(idbMap).length > 0) {
    try {
      localStorage.setItem("uploaded_prescriptions_by_category", JSON.stringify(idbMap));
      const firstCat = Object.keys(idbMap)[0];
      localStorage.setItem("uploaded_prescriptions", JSON.stringify(idbMap[firstCat]));
      localStorage.setItem("isPrescriptionFlow", "true");
      localStorage.setItem("prescriptionCategory", firstCat);
    } catch (e) {}
    return idbMap;
  }

  return {};
};

/**
 * Save category prescriptions to both LocalStorage and IndexedDB.
 */
export const persistCategoryPrescriptions = (categoryMap) => {
  if (!categoryMap || Object.keys(categoryMap).length === 0) {
    clearCategoryPrescriptions();
    return;
  }

  // 1. LocalStorage
  try {
    localStorage.setItem("uploaded_prescriptions_by_category", JSON.stringify(categoryMap));
    const firstCat = Object.keys(categoryMap)[0];
    localStorage.setItem("uploaded_prescriptions", JSON.stringify(categoryMap[firstCat]));
    localStorage.setItem("isPrescriptionFlow", "true");
    localStorage.setItem("prescriptionCategory", firstCat);
  } catch (e) {
    console.warn("LocalStorage save exceeded quota; IndexedDB will hold persistence:", e);
  }

  // 2. IndexedDB Backup
  saveToIndexedDB("uploaded_prescriptions_by_category", categoryMap);
};

/**
 * Remove an entire category prescription.
 */
export const removeCategoryPrescription = (category) => {
  const map = getStoredCategoryPrescriptionsSync();
  delete map[category];
  persistCategoryPrescriptions(map);
};

/**
 * Clear all category prescriptions from LocalStorage and IndexedDB.
 */
export const clearCategoryPrescriptions = () => {
  try {
    localStorage.removeItem("uploaded_prescriptions_by_category");
    localStorage.removeItem("uploaded_prescriptions");
    localStorage.removeItem("isPrescriptionFlow");
    localStorage.removeItem("prescriptionCategory");
  } catch (e) {}
  removeFromIndexedDB("uploaded_prescriptions_by_category");
};
